export default function Header() {
  const { pathname } = useLocation();
  const html = useMemo(() => {
    if (pathname === '/') return HEADER_HTML;
    return HEADER_HTML.replace('chr-header home', 'chr-header');
  }, [pathname]);

  useEffect(() => {
    const header = document.getElementById('chr-header');
    if (!header) return;

    const topItems = [...header.querySelectorAll('#menu-main-menu > li')];
    topItems.forEach((li) => {
      li.classList.remove(
        'current-menu-item',
        'current_page_item',
        'current-page-item',
        'current-menu-ancestor',
        'current_page_ancestor'
      );
    });
    header.querySelectorAll('#menu-main-menu > li > a[aria-current]').forEach((a) => {
      a.removeAttribute('aria-current');
    });

    const isServiceRoute =
      pathname === '/web-design' ||
      pathname.startsWith('/web-design/') ||
      pathname === '/ecommerce' ||
      pathname.startsWith('/ecommerce/') ||
      pathname === '/web-development' ||
      pathname.startsWith('/web-development/');

    let activeItem = null;
    let activeLink = null;

    if (isServiceRoute) {
      activeItem = header.querySelector('#menu-item-235');
      activeLink = activeItem?.querySelector(':scope > a') || null;
    } else {
      const topLinks = [...header.querySelectorAll('#menu-main-menu > li > a[href]')];
      activeLink = topLinks.find((a) => a.getAttribute('href') === pathname) || null;
      activeItem = activeLink?.closest('li') || null;
    }

    if (activeItem) {
      activeItem.classList.add('current-menu-item', 'current_page_item');
      activeLink?.setAttribute('aria-current', 'page');
    }
  }, [pathname]);

  return <div dangerouslySetInnerHTML={{ __html: html }} />;
}
